static void Gen_temporal_tsample(DataChunk &args, ExpressionState &state, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 4; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<string_t>(args.data[0]);
    auto in1 = FlatVector::GetData<interval_t>(args.data[1]);
    auto in2 = FlatVector::GetData<timestamp_tz_t>(args.data[2]);
    auto in3 = FlatVector::GetData<string_t>(args.data[3]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        bool valid = true;
        for (idx_t c = 0; c < 4; c++)
            if (!FlatVector::Validity(args.data[c]).RowIsValid(i)) { valid = false; break; }
        if (!valid) { outv.SetInvalid(i); continue; }
        Temporal *x0 = BlobToTemporal(in0[i]);
        Temporal *r = (Temporal *) temporal_tsample(x0, MeosIntervalArg(in1[i]), DuckDBToMeosTimestamp(in2[i]).value, interptype_from_string(in3[i].GetString().c_str()));
        free(x0);
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = TemporalToBlob(result, r);
    }
    if (rows == 1) result.SetVectorType(VectorType::CONSTANT_VECTOR);
}

