            if (!FlatVector::Validity(args.data[c]).RowIsValid(i)) { valid = false; break; }
        if (!valid) { outv.SetInvalid(i); continue; }
        Temporal *x0 = BlobToTemporal(in0[i]);
        Temporal *r = (Temporal *) temporal_tsample(x0, MeosIntervalArg(in1[i]), DuckDBToMeosTimestamp(in2[i]).value, interptype_from_string("discrete"));
        free(x0);
